const exportWorkItems = `-- name: ExportWorkItems :many
SELECT s.record_id, s.changed_at, s.payload
FROM (
  SELECT (w.id)::text AS record_id,
         w.updated_at AS changed_at,
         (to_jsonb(w) - 'tenant_id')::jsonb AS payload,
         w.id AS key_1
  FROM work_item w
) s
  WHERE ($1::timestamptz IS NULL OR s.changed_at > $1::timestamptz)
    AND (s.changed_at, s.key_1) > ($2::timestamptz, $3::uuid)
  ORDER BY s.changed_at, s.key_1
  LIMIT $4::int
`

type ExportWorkItemsParams struct {
	Since   pgtype.Timestamptz
	AfterAt pgtype.Timestamptz
	AfterID pgtype.UUID
	Batch   int32
}

type ExportWorkItemsRow struct {
	RecordID  string
	ChangedAt pgtype.Timestamptz
	Payload   []byte
}

func (q *Queries) ExportWorkItems(ctx context.Context, arg ExportWorkItemsParams) ([]ExportWorkItemsRow, error) {
	rows, err := q.db.Query(ctx, exportWorkItems,
		arg.Since,
		arg.AfterAt,
		arg.AfterID,
		arg.Batch,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ExportWorkItemsRow{}
	for rows.Next() {
		var i ExportWorkItemsRow
		if err := rows.Scan(&i.RecordID, &i.ChangedAt, &i.Payload); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

